def baseline_legacy(apps, schema_editor):
    alias = schema_editor.connection.alias
    models_by_group = {key: apps.get_model("radar", name) for key, name in
        (("types", "ObjectType"), ("properties", "PropertyDefinition"), ("relations", "RelationType"))}
    state_model = apps.get_model("radar", "WorkspaceSchemaState")
    history = apps.get_model("radar", "SchemaUpgrade")
    workspaces = set()
    for model in models_by_group.values():
        workspaces.update(model.objects.using(alias).values_list("workspace_id", flat=True))
    for workspace_id in workspaces:
        ids, divergences = {}, []
        records = {}
        for group, model in models_by_group.items():
            rows = model.objects.using(alias).filter(workspace_id=workspace_id).order_by("created_at", "id")
            if group == "properties":
                rows = rows.select_related("object_type")
            for row in rows:
                key = f"{row.object_type.key}.{row.key}" if group == "properties" else row.key
                records[f"{group}:{key}"] = row
        for key, base in BASE_DEFINITIONS.items():
            row = records.get(key)
            if row is None or not row.is_system:
                divergences.append({"key": key, "reason": "missing" if row is None else "unmanaged"})
                continue
            ids[key] = str(row.pk)
            local = {field: getattr(row, field) for field in base}
            if local != base or row.deleted_at:
                divergences.append({"key": key, "reason": "local_difference", "local": local, "deleted": bool(row.deleted_at)})
        state_model.objects.using(alias).create(workspace_id=workspace_id, origin="legacy", revision=1,
            installed_base={"definitions": BASE_DEFINITIONS, "ids": ids}, divergences=divergences)
        history.objects.using(alias).create(workspace_id=workspace_id, to_version="legacy-baseline", package_hash="",
            diff={"kind": "migration_baseline", "divergences": divergences})


